/**
 * Candidate target profile for a disease, derived from Open Targets association metadata. Nothing is generated by a model.
 * An association score is not causation, efficacy or target validation; a listed target is a candidate to investigate, not a
 * recommendation, and nothing here is clinical or treatment advice. Missing evidence types are stated, not hidden.
 */
import type {OpenTargetsDiseaseRecord} from "../evidence/openTargetsLookup";

/** Open Targets evidence-type (datatype) ids, with plain labels (checked against the live API 15 Nov 2026: the former "known_drug" type is now "clinical"). Unknown datatypes returned by the provider are kept and labelled as returned. */
export const DATATYPES:readonly {id:string;label:string}[]=[
 {id:"genetic_association",label:"Human genetics"},{id:"somatic_mutation",label:"Somatic mutation"},{id:"clinical",label:"Clinical precedence"},
 {id:"affected_pathway",label:"Affected pathway"},{id:"rna_expression",label:"RNA expression"},{id:"literature",label:"Literature"},{id:"animal_model",label:"Animal model"},
];
export type TargetCandidate={
 rank:number;ensemblId:string;symbol:string;score:number;
 evidence:{id:string;label:string;score:number|null}[];
 present:string[];absent:string[];
 /** Plain observations derived only from which evidence types are present or absent. */
 observations:string[];
};
export type TargetProfile={
 diseaseId:string;diseaseName:string;retrievedAt:string;associationScope:"direct"|"indirect_enabled";totalAssociations:number;shown:number;
 candidates:TargetCandidate[];
 honesty:{scoreIsNotCausation:true;scoreIsNotEfficacy:true;scoreIsNotTargetValidation:true;notARecommendation:true;noClinicalAdvice:true};
};
export const TARGET_CAVEAT="A score summarises public evidence of association between a target and a disease. It is not evidence that changing the target would help, and it is not a recommendation.";

export function profileTargets(rec:OpenTargetsDiseaseRecord,limit=15):TargetProfile{
 const label=new Map(DATATYPES.map(d=>[d.id,d.label]));
 const rows=[...rec.associations].sort((a,b)=>b.score-a.score||a.approvedSymbol.localeCompare(b.approvedSymbol)).slice(0,limit);
 const candidates=rows.map((r,i):TargetCandidate=>{
  const by=new Map(r.datatypeScores.map(d=>[d.id,d.score]));
  const evidence=[...DATATYPES.map(d=>({id:d.id,label:d.label,score:by.has(d.id)&&by.get(d.id)!>0?by.get(d.id)!:null})),
   ...r.datatypeScores.filter(d=>!label.has(d.id)&&d.score>0).map(d=>({id:d.id,label:d.id.replace(/_/g," "),score:d.score}))];
  const present=evidence.filter(e=>e.score!==null).map(e=>e.id),absent=evidence.filter(e=>e.score===null).map(e=>e.id);
  const o:string[]=[];
  if(!present.includes("genetic_association"))o.push("No human genetic association evidence is recorded for this target and disease.");
  if(!present.includes("clinical")&&!present.includes("known_drug"))o.push("No clinical-precedence evidence (drugs or trials) is recorded for this target and disease.");
  if(present.length===1)o.push(`All recorded evidence is one type (${evidence.find(e=>e.score!==null)!.label.toLowerCase()}).`);
  if(present.length>0&&present.every(id=>id==="literature"||id==="animal_model"))o.push("Recorded evidence is limited to literature and animal models.");
  return {rank:i+1,ensemblId:r.targetEnsemblId,symbol:r.approvedSymbol,score:r.score,evidence,present,absent,observations:o};
 });
 return {diseaseId:rec.diseaseId,diseaseName:rec.diseaseName,retrievedAt:rec.retrievedAt,associationScope:rec.associationScope,totalAssociations:rec.associationCount,shown:candidates.length,candidates,
  honesty:{scoreIsNotCausation:true,scoreIsNotEfficacy:true,scoreIsNotTargetValidation:true,notARecommendation:true,noClinicalAdvice:true}};
}
